// The Native stack mounts only its first route; AppNavigator retains its real
// session branch and screen lifetime. No screen/controller is substituted.
vi.mock("@react-navigation/native-stack",async()=>{
 const React=await import("react");
 const first=(children:any):any=>{for(const child of React.Children.toArray(children)){if(React.isValidElement(child)){if(child.type===React.Fragment){const found=first((child.props as any).children);if(found)return found;}else return child;}}return null;};
 return {createNativeStackNavigator:()=>({Navigator:({children}:any)=>first(children),Screen:({component:Component}:any)=>Component?React.createElement(Component,{navigation:{navigate:()=>{},popToTop:()=>{},replace:()=>{}}}):null})};
});

const USER="a".repeat(32),OTHER="b".repeat(32),SALT=Buffer.alloc(16,3),PASSWORD="the account's known password",RANDOM_DATA=Buffer.alloc(32,7);
function derive(password=PASSWORD){const master=crypto.pbkdf2Sync(password,SALT,600000,32,"sha256");return {masterKey:master,authKey:Buffer.from(crypto.hkdfSync("sha256",master,Buffer.alloc(32),Buffer.from("mindpattern/auth/v1"),32)),dataKey:Buffer.from(crypto.hkdfSync("sha256",master,Buffer.alloc(32),Buffer.from("mindpattern/data/v1"),32))};}
const known=derive();
function envelope(cost=600000,password=PASSWORD,dataKey=RANDOM_DATA){const params={algorithm:"pbkdf2-sha256",version:1,iterations:cost},master=crypto.pbkdf2Sync(password,SALT,cost,32,"sha256"),key=Buffer.from(crypto.hkdfSync("sha256",master,SALT,Buffer.from("mindpattern/envelope/v2"),32)),nonce=Buffer.alloc(12,6),cipher=crypto.createCipheriv("aes-256-gcm",key,nonce);cipher.setAAD(Buffer.from(JSON.stringify({context:"envelope",kdf_params:params,username:"alice"})));return {key_scheme:"v2",salt:SALT.toString("base64"),kdf_params:params,wrapped_data_key:Buffer.concat([nonce,cipher.update(dataKey),cipher.final(),cipher.getAuthTag()]).toString("base64")};}
type Root=ReturnType<typeof ReactTestRenderer.create>;
let root:Root|undefined,saltStatus:number,loginStatus:number,envelopeStatus:number,envelopeValue:unknown,loginOwner:string,serverSalt:Buffer,serverVerifier:string,rekeyStatus:number;
const nativeDelete=files.deleteAsync.getMockImplementation()!;
beforeEach(async()=>{
 vi.useRealTimers();vi.restoreAllMocks();storage.__reset();files.__resetFiles();files.deleteAsync.mockImplementation(nativeDelete);keychain.__reset();keychain.__setBiometryType(null);runTestControl(setSecureStoreBackend,null);runTestControl(__resetLocalKeyLifecycleForTests);vault.lock();Alert.alert.mockClear();saltStatus=200;loginStatus=0;envelopeStatus=404;envelopeValue=undefined;loginOwner=USER;serverSalt=Buffer.from(SALT);serverVerifier=known.authKey.toString("base64");rekeyStatus=200;
 await api.setSession("native-bearer",USER,"alice");await api.cacheSalt("alice",SALT.toString("base64"));await storeUnlockProof(known.dataKey,USER);
 vi.stubGlobal("fetch",async(url:string,init:RequestInit)=>{const path=new URL(url).pathname,body=init.body?JSON.parse(String(init.body)):null;let value:unknown={},status=200;if(path.endsWith("/auth/salt")){status=saltStatus;value={salt:serverSalt.toString("base64")};}else if(path.endsWith("/auth/login")){status=loginStatus||(body.verifier===serverVerifier?200:401);value=status===200?{token:"fresh-native-bearer",user_id:loginOwner}:{detail:"untrusted server feedback"};}else if(path.endsWith("/auth/key-envelope")){status=envelopeStatus;value=envelopeValue??{detail:"legacy server endpoint"};}else if(path.endsWith("/account/password")){status=rekeyStatus;if(status===200){serverSalt=Buffer.from(body.new_salt,"base64");serverVerifier=body.new_verifier;envelopeValue={key_scheme:"v2",salt:body.new_salt,kdf_params:body.new_kdf_params??{algorithm:"pbkdf2-sha256",version:1,iterations:600000},wrapped_data_key:body.wrapped_data_key};}else value={detail:"native password transaction unavailable"};}else if(path.endsWith("/processing/sessions"))value={session_token:"native-processing-receipt"};else if(path.endsWith("/consents"))value=[];else if(path.endsWith("/processing/rekey")){status=rekeyStatus;if(status===200){serverSalt=Buffer.from(body.new_salt,"base64");serverVerifier=body.new_verifier;value={credential_rotated:true,operation_id:body.operation_id,entries:1,insights:0,measures:0,consents_rewrapped:0,recovery_invalidated:true};}else value={detail:"native atomic transaction unavailable"};}else if(path.endsWith("/insights"))value={active_days:5};else if(path.endsWith("/meta"))value={unlock_days:30};else if(path.endsWith("/auth/logout"))value={};else throw new Error("unexpected native route "+path);const response=new Response(JSON.stringify(value),{status});Object.defineProperty(response,"url",{value:url});return response;});
});
afterEach(async()=>{assertPublicSurface({view:root?publicSurface(root):null,alerts:Alert.alert.mock.calls.map(([title,message,buttons])=>({title,message,buttons:buttons?.map((button:any)=>({text:button.text,style:button.style}))}))},1);if(root){await act(async()=>root!.unmount());root=undefined;}vi.useRealTimers();vi.restoreAllMocks();vault.lock();await api.clearSession();vi.unstubAllGlobals();});
async function mount(){await act(async()=>{root=ReactTestRenderer.create(<ThemeProvider><SessionProvider><UnlockScreen navigation={{navigate:()=>{}}}/></SessionProvider></ThemeProvider>);});for(let i=0;i<32;i++)await act(async()=>{await Promise.resolve();});}
function password(){return root!.root.findAllByType(TextInput).find(node=>node.props.accessibilityLabel==="Password")!;}
async function type(value=PASSWORD){await act(async()=>password().props.onChangeText(value));}
function button(label="Unlock"){return root!.root.findAllByType(TouchableOpacity).find(node=>node.props.accessibilityLabel===label)!;}
async function unlock(){expect(button()).toBeDefined();expect(button().props.disabled).not.toBe(true);await act(async()=>{await button().props.onPress();});}
