it.each([600000,800000])("opens the native random-data envelope with its declared %s derivation cost",async cost=>{envelopeStatus=200;envelopeValue=envelope(cost);await mount();await type();await unlock();expect(vault.get()).toMatchObject({dataKey:RANDOM_DATA,authKey:known.authKey,authKeyKnown:true});expect(await verifyUnlockProof(RANDOM_DATA,USER)).toBe("ok");expect(password().props.value).toBe("");expect(Alert.alert.mock.calls).toEqual([]);});
it.each(["legacy","v2"])("opens a verified native %s account offline while retaining its existing bearer",async scheme=>{saltStatus=500;if(scheme==="v2"){const row=envelope();await cacheEnvelope("alice",{scheme:"v2",saltB64:row.salt,kdfParams:row.kdf_params as any,wrappedB64:row.wrapped_data_key});}await mount();await type();await unlock();expect(vault.get().dataKey).toEqual(scheme==="v2"?RANDOM_DATA:known.dataKey);expect(await secureStore.getItem("@mindpattern/token")).toBe("native-bearer");expect(Alert.alert.mock.calls).toEqual([]);});
it("keeps the real password input private and refuses empty accessible unlock activation",async()=>{await mount();expect(password().props).toMatchObject({secureTextEntry:true,textContentType:"password",autoComplete:"current-password",value:""});expect(button().props.disabled).toBe(true);await act(async()=>{await password().props.onSubmitEditing();});expect(vault.isUnlocked()).toBe(false);expect(Alert.alert.mock.calls).toEqual([]);});
it.each(["missing username","missing owner","missing offline salt","missing offline proof","unconfirmed scheme","invalid scheme"])("refuses native unlock with %s and leaves its key vault locked",async failure=>{if(failure==="missing username")await secureStore.removeItem("@mindpattern/username");if(failure==="missing owner")await secureStore.removeItem("@mindpattern/user_id");if(failure==="missing offline salt"){saltStatus=500;await api.clearCachedSalt("alice");}if(failure==="missing offline proof"){saltStatus=500;await storage.removeItem(accountStorageKey.unlockProof(USER));}if(failure==="unconfirmed scheme")envelopeStatus=500;if(failure==="invalid scheme"){envelopeStatus=200;envelopeValue={key_scheme:"v3",salt:SALT.toString("base64"),kdf_params:null,wrapped_data_key:null};}await mount();await type();await unlock();expect(vault.isUnlocked()).toBe(false);expect(Alert.alert.mock.calls).toHaveLength(1);expect(password().props.value).toBe(PASSWORD);});
it("rejects a native login proof returning another account without adopting its bearer",async()=>{loginOwner=OTHER;await mount();await type();await unlock();expect(vault.isUnlocked()).toBe(false);expect(await secureStore.getItem("@mindpattern/token")).toBe("native-bearer");expect(Alert.alert.mock.calls).toHaveLength(1);});
it("restores native biometric local decryption with an unknown auth key and clears the password input",async()=>{keychain.__setBiometryType("FaceID");await enableBiometricUnlock(USER,known.dataKey);await mount();await type();expect(button("Unlock with biometrics")).toBeDefined();await act(async()=>button("Unlock with biometrics").props.onPress());await vi.waitFor(()=>expect(vault.isUnlocked()).toBe(true));expect(vault.get()).toMatchObject({dataKey:known.dataKey,authKey:Buffer.alloc(32),authKeyKnown:false});expect(password().props.value).toBe("");expect(await hasBiometricUnlock(USER)).toBe(true);});
it.each(["unmount","replacement credentials"])("erases a held native password allocation after %s without unlocking the abandoned screen",async retirement=>{await mount();await type();const pbkdf=engine.pbkdf2;let ready!:()=>void,release:()=>void=()=>{},allocation:Buffer|undefined;const started=new Promise<void>(resolve=>{ready=resolve;});vi.spyOn(engine,"pbkdf2").mockImplementation(((...args:any[])=>{const callback=args.pop();return (pbkdf as(...values:any[])=>unknown)(...args,(error:Error|null,key:Buffer)=>{allocation=key;ready();release=()=>callback(error,key);});}) as any);let pending!:Promise<void>;await act(async()=>{pending=button().props.onPress();await Promise.race([started,pending]);});if(retirement==="unmount"){await act(async()=>{root!.unmount();root=undefined;});}else{await api.setSession("replacement-bearer",OTHER,"bob");vault.unlock({masterKey:Buffer.alloc(32),authKey:Buffer.alloc(32,12),dataKey:Buffer.alloc(32,13)},OTHER);}try{await act(async()=>{release();await pending;});expect(allocation).toBeDefined();expect(allocation!.every(byte=>byte===0)).toBe(true);expect(vault.isUnlocked()).toBe(retirement!=="unmount");if(retirement!=="unmount"){expect(vault.ownerUserId()).toBe(OTHER);expect(vault.get().dataKey).toEqual(Buffer.alloc(32,13));expect(await secureStore.getItem("@mindpattern/token")).toBe("replacement-bearer");}expect(Alert.alert.mock.calls).toEqual([]);}finally{release();await pending;}});
