 await mount();await type();const from=Buffer.from,allocations:Buffer[]=[];vi.spyOn(Buffer,"from").mockImplementation(((...args:any[])=>{const value=(from as(...args:any[])=>Buffer)(...args);if(args[0] instanceof Uint8Array&&!Buffer.isBuffer(args[0])&&(value.equals(known.authKey)||value.equals(known.dataKey)))allocations.push(value);return value;}) as any);
