function nativeDerivationDelivery(){
 const derive=engine.pbkdf2;let delivered!:()=>void;const complete=new Promise<void>(resolve=>{delivered=resolve;});vi.spyOn(engine,"pbkdf2").mockImplementation(((...args:any[])=>{const callback=args.pop();return (derive as(...values:any[])=>unknown)(...args,(error:Error|null,key:Buffer)=>{callback(error,key);delivered();});}) as any);return complete;
}
