 if(mode==="online")loginStatus=401;else saltStatus=500;await mount();await type("another password");const delivered = nativeDerivationDelivery();vi.useFakeTimers({toFake:["setTimeout","clearTimeout"]});let pending!:Promise<void>;await act(async()=>{pending=button().props.onPress();await Promise.race([delivered,pending]);for(let i=0;i<256;i++)await Promise.resolve();});
