async function prepareInterruptedRotation(withCheckpointSalt=true,nativeRoot=false){
 const chosen="the account's previously chosen new password",salt=Buffer.alloc(16,12),master=crypto.pbkdf2Sync(chosen,salt,600000,32,"sha256"),dataKey=Buffer.from(crypto.hkdfSync("sha256",master,Buffer.alloc(32),Buffer.from("mindpattern/data/v1"),32));
 await storage.setItem(accountStorageKey.pendingRotationSalt(USER),salt.toString("base64"));await prepareLocalRekey(USER,known.dataKey,dataKey,withCheckpointSalt?{oldSaltB64:SALT.toString("base64")}:undefined);master.fill(0);dataKey.fill(0);if(nativeRoot)await mountNavigator();else await mount();await vi.waitFor(()=>expect(button("Finish interrupted password change")).toBeDefined());return chosen;
}
it("finishes a real native interrupted rotation and permits a fresh unlock with its chosen password",async()=>{
 const chosen=await prepareInterruptedRotation();const newInput=root!.root.findAllByType(TextInput).find(node=>node.props.accessibilityLabel==="Previously chosen new password")!;expect(newInput.props).toMatchObject({secureTextEntry:true,autoCapitalize:"none",autoCorrect:false,value:""});await type();await act(async()=>newInput.props.onChangeText(chosen));await act(async()=>button("Finish interrupted password change").props.onPress());
 await vi.waitFor(()=>expect(Alert.alert.mock.calls).toEqual([["Password changed","The password change is complete. Unlock with your new password."]]),{timeout:30000});expect(await pendingLocalRekey(USER)).toBe(false);expect(vault.isUnlocked()).toBe(false);expect(password().props.value).toBe("");expect(button("Finish interrupted password change")).toBeUndefined();await type(chosen);await unlock();expect(vault.ownerUserId()).toBe(USER);expect(vault.isUnlocked()).toBe(true);expect(await verifyUnlockProof(vault.get().dataKey,USER)).toBe("ok");
});
it("keeps the original native checkpoint and explains an interrupted rotation refused by the endpoint",async()=>{
 const chosen=await prepareInterruptedRotation();rekeyStatus=500;await type();await act(async()=>root!.root.findAllByType(TextInput).find(node=>node.props.accessibilityLabel==="Previously chosen new password")!.props.onChangeText(chosen));await act(async()=>button("Finish interrupted password change").props.onPress());await vi.waitFor(()=>expect(Alert.alert.mock.calls).toHaveLength(1),{timeout:30000});expect(Alert.alert.mock.calls[0]![0]).toBe("Could not change password");expect(await pendingLocalRekey(USER)).toBe(true);expect(vault.isUnlocked()).toBe(false);expect(password().props.value).toBe(PASSWORD);expect(button("Finish interrupted password change")).toBeDefined();
});

