   if(armed&&key==="@mindpattern/username"){
    armed=false;let remaining=phase;const next=()=>{if(--remaining>0)queueMicrotask(next);else{delivered=true;if(root!.root.findAllByType(UnlockScreen).length){retired=true;button("Sign out instead").props.onPress();}}};queueMicrotask(next);
   }
