it.each(["after route commit","before route commit"])("keeps queued Native keyboard submissions retired while Root signout awaits its credential receipt: %s",async delivery=>{
 await mountNavigator();await type();await secureStore.removeItem("@mindpattern/username");
 const read=storage.getItem.bind(storage);let usernames=0,owners=0;let releaseFirst!:()=>void,releaseSecond!:()=>void,releaseOwner!:()=>void;
 const firstReceipt=new Promise<void>(resolve=>{releaseFirst=resolve;}),secondReceipt=new Promise<void>(resolve=>{releaseSecond=resolve;}),ownerReceipt=new Promise<void>(resolve=>{releaseOwner=resolve;});
 vi.spyOn(storage,"getItem").mockImplementation(async slot=>{
  const value=await read(slot);
  // Native storage has completed these reads. Hold only bridge delivery;
  // the physical executor remains free for the current signout cleanup.
  if(slot==="@mindpattern/username"){
   const receipt=++usernames;
   if(receipt===1)await firstReceipt;
   if(receipt===3)await secondReceipt;
  }
  if(slot==="@mindpattern/user_id"&&++owners===1)await ownerReceipt;
  return value;
 });
 let second:Promise<void>|undefined,third:Promise<void>|undefined;
 try{
  // Fabric can batch already queued native events before committing the
  // parent's logged-out route. Every input reads its current installed props.
  await act(async()=>{
   const first=password().props.onSubmitEditing();button("Sign out instead").props.onPress();second=password().props.onSubmitEditing();
   for(let i=0;i<32;i++)await Promise.resolve();releaseFirst();await first;
   if(delivery==="before route commit"){releaseSecond();await second;}
   third=password().props.onSubmitEditing();if(delivery==="before route commit")await third;
  });
  expect(Alert.alert.mock.calls).toEqual([]);
  releaseOwner();releaseSecond();await Promise.all([second,third]);
  await vi.waitFor(async()=>expect(await secureStore.getItem("@mindpattern/token")).toBeNull(),{timeout:1500});
  expect(root!.root.findAllByType(UnlockScreen)).toHaveLength(0);expect(vault.canReauthenticate()).toBe(false);expect(Alert.alert.mock.calls).toEqual([]);
 }finally{releaseFirst();releaseSecond();releaseOwner();await Promise.all([second,third]);}
});
